  "• Tek dünya: tüm oyuncular aynı olasılık tablosunu kullanır.": "• Un seul monde : tous les joueurs utilisent la même table de probabilités.",
  "• Elmas tavanı dolduysa fazlası euro karşılığı ödenir.": "• Si le plafond de diamants est atteint, l'excédent est payé en euros.",
