  "Maç, turnuva ve lig sıralama ödülleri": "Récompenses de match, de tournoi et de classement du championnat",
  "Maç, lig ve turnuva ödülleri otomatik olarak": "Les récompenses de match, de championnat et de tournoi sont automatiquement",
  "ödenir. Ödeme günleri: sezonun": "versées. Jours de paiement de la saison :",
  "Antrenman, seçtiğin yeteneğe": "L'entraînement rapporte à la compétence choisie",
  "kazandırır; yetenek seviyen yükseldikçe oyuncu gücün (OVR) artar.": "; plus ton niveau de compétence monte, plus ta force (OVR) augmente.",
  ". İstediğin gruptan çalışabilirsin.": ". Tu peux t'entraîner dans le groupe de ton choix.",
  ". Farklı gruba (Kaleci / Defans / Orta Saha / Forvet) geçişte": ". En changeant de groupe (Gardien / Défense / Milieu / Attaque)",
  "ve o grubun yeni yetenekleri 10'dan başlar.": "et les nouvelles compétences de ce groupe démarrent à 10.",
  "eşittir (Sv.1 → 1 eş zamanlı).": "est égal (Niv.1 → 1 simultané).",
  "ile başlarsın. Takım tesisin (Performans Merkezi) her seviye için": "au départ. Ton installation d'équipe (Centre de performance) ajoute pour chaque niveau",
  "harcama; hangisi önce dolarsa orada durur.": "de dépenses ; la première limite atteinte s'applique.",
  "işlenir, her bilet denetim için kaydedilir.": "est traité, et chaque ticket est enregistré pour contrôle.",
  "kazanır. Elmas ortalama her 200 bilette bir çıkar.": "gagne. Un diamant sort en moyenne tous les 200 tickets.",
  "'de sıfırlanır. Kazanç tavanı Toto ile ortaktır.": ". Le plafond de gains est partagé avec Toto.",
  "Ücretsiz günlük bilet 25'e sayılmaz. Tüm sayaçlar": "Le ticket quotidien gratuit ne compte pas dans les 25. Tous les compteurs se réinitialisent à",
  "güncel sezon maaşı ÷ 4": "salaire de saison actuel ÷ 4",
  "ve talep ettiğin": "et le montant demandé en",
  "(final galibi) ayrıca": "(vainqueur de la finale) reçoit aussi",
  "de buluşur. Final hariç tüm turlar çift maçlıdır.": "se retrouvent. Tous les tours sauf la finale se jouent en aller-retour.",
  ". Lig sonunda hak kazanan takımlar turnuvalara katılır.": ". Les équipes qualifiées en fin de championnat participent aux tournois.",
  "olarak katılacaksın. İstediğin zaman ayrılabilirsin.": "sera ton rôle en rejoignant l'équipe. Tu peux partir à tout moment.",
  ". Diğer üyeler oylarını veriyor.": ". Les autres membres votent.",
  ". Sonraki seçimde tekrar başvurabilirsin.": ". Tu pourras te représenter à la prochaine élection.",
  "Karşı takım kaptanı kabul ederse maç planlanır.": "Le match est programmé si le capitaine adverse accepte.",
  "(Sahadan çıkarmak için diziliş ekranında yedeğe sürükleyin.)": "(Pour sortir un joueur, fais-le glisser vers les remplaçants sur l'écran de formation.)",
  ". Tüm takımlar, oyuncular ve maçlar kurgusaldır.": ". Toutes les équipes, tous les joueurs et tous les matchs sont fictifs.",
  ". Katılım yalnızca oyun içi sanal para ile yapılır;": ". La participation se fait uniquement avec de la monnaie virtuelle du jeu ;",
