  "Toplam Kupa ›": "Total trophées ›",
  "belirlenir: oyuncunun güncel yetenek seviyesine göre hesaplanır, oyuncu geliştikçe maaşı artar. Her maaş gününde": "est fixé automatiquement : il est calculé selon le niveau de compétence actuel du joueur, donc le salaire augmente à mesure qu'il progresse. À chaque jour de paie",
