  "eklenir. Transferler ve oyuncu maaşları finanstan ödenir. Bağış yaparak finansa kişisel destek verebilirsin.": "est ajouté. Les transferts et les salaires des joueurs sont payés par les finances. Tu peux soutenir personnellement les finances en faisant un don.",
