  "Antrenman süresi uzadıkça kazanım artar, ama daha çok enerji ve süre ister.": "Plus la séance est longue, plus le gain est grand, mais elle coûte plus d'énergie et de temps.",
  "Düzenli antrenman, takımdaki yerini ve transfer değerini yükseltmenin en hızlı yoludur.": "L'entraînement régulier est le moyen le plus rapide d'améliorer ta place dans l'effectif et ta valeur de transfert.",
  "Enerji sunucu saatiyle (UTC 00:00) yenilenir. Bu, her ülkede aşağıdaki yerel saate denk gelir:": "L'énergie se recharge à l'heure du serveur (UTC 00:00). Cela correspond à l'heure locale suivante dans chaque pays :",
