  "Bu ülkede takım sahibi olan tüm kaptanlar otomatik olarak federasyon üyesidir. Sezon sonu seçimde her üyenin": "Tout capitaine possédant une équipe dans ce pays est automatiquement membre de la fédération. Lors de l'élection de fin de saison, chaque membre dispose de",
