  "🏟️ Takımlar": "🏟️ Équipes",
  "💡 Diamond ile oyuncu transfer eder, tesis yükseltir, item ve takım satın alabilirsin. Büyük paketler kademeli bonus kazandırır.": "💡 Utilise les diamants pour recruter des joueurs, améliorer les installations et acheter des objets ou des équipes. Les gros packs offrent des bonus progressifs.",
