  "Yüksek seviyeli antrenmanlar daha çok enerji harcar — verimli puan demek.": "Les séances de niveau supérieur coûtent plus d'énergie — donc des points plus efficaces.",
  "Kadronu kontrol et, akıllı kadro öner butonuyla en iyi 11'i hızlıca diz!": "Vérifie ton effectif — utilise le bouton d'effectif intelligent pour aligner vite le meilleur onze !",
  "Sahadaki oyuncuya dokun → yedeklerden birini seç. Sürüklemek için karta": "Touche un joueur sur le terrain → choisis un remplaçant. Pour glisser, sur la carte",
  "seçildi → sahadan değişecek oyuncuyu seç.": "sélectionné → choisis le joueur qui sort.",
  "Hazırlıklarını yap. Strateji ve kadro ayarlarını gözden geçir.": "Prépare-toi. Revois ta stratégie et les réglages de ton effectif.",
  "Bir sonraki sezon hazırlıkları için kadronu yeniden şekillendirme zamanı.": "Il est temps de remodeler ton effectif pour la saison prochaine.",
  "kadronu güçlendirmek, sakat veya formdan düşen oyuncularını değiştirmek için": "pour renforcer ton effectif et remplacer les joueurs blessés ou en méforme",
  "• Bitkin oyuncular maçta düşük performans gösterir ve sakatlanma riski artar.": "• Les joueurs épuisés jouent mal et risquent davantage de se blesser.",
