  "Bir hafta boyunca oynadığın tüm maçların reytinglerinin": "Des notes de tous les matchs que tu joues pendant une semaine,",
  "alan oyuncular yarışır. Maç motoru her maçta oyuncularının performansını 17 farklı kategoride değerlendirir ve bir maç sonu reytingi üretir.": "joueurs s'affrontent. Le moteur de match évalue la performance de chaque joueur dans 17 catégories et produit une note d'après-match.",
  "oyuncular yarışır. Antrenman seansı yaptığında harcadığın enerji bu yarışın puanına eklenir.": "joueurs s'affrontent. L'énergie dépensée en séances d'entraînement compte pour cette course.",
  "Ödülünü ödül penceresi içinde toplamazsan iptal olur. Yeni yarış başladıktan sonra eski ödüller kaybolur.": "Si tu ne réclames pas ta récompense dans le délai prévu, elle est annulée. Les anciennes récompenses sont perdues dès qu'une nouvelle course commence.",
  "✅ Bu serideki tüm hediyelerini topladın. Yarın da gir, seri devam etsin!": "✅ Tu as récupéré tous les cadeaux de cette série. Reviens demain pour la prolonger !",
  "🚪 Her gün giriş yap, serini büyüt! İlk gün hediyesi seni bekliyor.": "🚪 Connecte-toi chaque jour pour allonger ta série ! Ton cadeau du premier jour t'attend.",
  "toplanmamış hediyen var! Toplamadan gün kaçırırsan yanar.": "cadeaux non récupérés ! Si tu rates un jour sans les récupérer, ils expirent.",
  "Bir takıma katılıp maç oynadığında buraya yansıyacak.": "Ceci se remplira dès que tu rejoindras une équipe et joueras des matchs.",
  "Takım Puanı her resmi maç sonucunun kademe çarpanıyla hesaplanır (Takımlar sekmesindeki bilgi kutusuyla aynı çarpanlar).": "Les Points d'équipe sont calculés à partir de chaque résultat officiel avec le multiplicateur de division (les mêmes que dans l'encadré de l'onglet Équipes).",
  "maç sonucu, oynanan kademenin çarpanıyla puana çevrilip toplanır. Hazırlık ve milli maçlar sayılmaz.": "les résultats des matchs sont convertis en points via le multiplicateur de la division, puis additionnés. Les matchs amicaux et internationaux ne comptent pas.",
  "takımlar arasında gerçek küresel sıradır.": "est le véritable classement mondial des équipes.",
  "katkısı sayılır; 6. sezon başlayınca en eski sezon düşer. Her sezonun katkısı satırdaki kartlarda ayrı görünür.": "compte ; au début de la saison 6, la plus ancienne saison est retirée. La contribution de chaque saison apparaît séparément sur les cartes de la ligne.",
  "her ülkenin Süper Lig'inde 1-6. sıralar belirlenir": "les places 1 à 6 sont déterminées dans la Super Ligue de chaque pays",
