  "sonu sıralamasından · Play-Off'a gidecek takımlar": "classement final · équipes qualifiées pour le Play-Off",
  "En iyi 50 oyuncu listelenir; kendi oyuncun listede yoksa en altta gerçek sıranla görünür.": "Les 50 meilleurs joueurs sont listés ; si ton joueur n'en fait pas partie, il apparaît en bas avec son vrai rang.",
