  "Sözleşmesiz: oyuncu istediği zaman ayrılır. Sözleşmeli: süre (1-5 sezon) bitene dek ayrılamaz. İkisinde de oyuncu sistem maaşını alır.": "Sans contrat, le joueur peut partir à tout moment. Sous contrat, il ne peut pas partir avant la fin de la durée (1–5 saisons). Dans les deux cas, le joueur perçoit le salaire système.",
