  "düşer. Maaş, ödeme günlerinde yatar; ilk ödeme katıldığı günden itibaren orantılıdır.": "baisse. Les salaires sont versés les jours de paie ; le premier paiement est calculé au prorata depuis son arrivée.",
  "kasasına aktarılır. Maaş 4 taksit halinde (gün 10/20/30/40) sezonun her çeyreğinde ödenir.": "est versé à la trésorerie. Le salaire est payé en 4 versements (jours 10/20/30/40), un par quart de saison.",
