  "💡 Bu takımın kaptanı kadrosunu büyütmediği için yeni istek kabul edilemez. Başka bir takım dene veya bekle.": "💡 Le capitaine de cette équipe n'a pas agrandi l'effectif, les nouvelles demandes ne peuvent donc pas être acceptées. Essaie une autre équipe ou patiente.",
