  "ile olan tüm konuşma silinecek. Bu işlem geri alınamaz.": "toute ta conversation avec lui sera supprimée. Cette action est irréversible.",
  "Seçimler her sezonun 1–3. günleri arasında yapılır; sonuçlar 3. gün 19:00'da açıklanır.": "Les élections ont lieu du 1er au 3e jour de chaque saison ; les résultats sont annoncés le jour 3 à 19:00.",
  "Tüm üyeler istediği zaman aday olabilir; en yüksek 5 etki kullanıcıya bonus aday olur": "Tout membre peut se présenter à tout moment ; les 5 utilisateurs ayant le plus d'influence deviennent candidats bonus",
