  "federasyon seçiminde kime oy verdiğin hiç kimseye gösterilmez.": "ton vote à l'élection de la fédération n'est jamais montré à personne.",
  "Bu federasyonun üyesi değilsin (izleyici modu). Aday olamaz veya oy veremezsin.": "Tu n'es pas membre de cette fédération (mode spectateur). Tu ne peux ni te présenter ni voter.",
  "Bir sonraki sezon tekrar aday olabilirsin.": "Tu pourras te représenter la saison prochaine.",
  "Federasyon Yetkiler sekmesinden detayları görebilirsin.": "Tu peux voir les détails dans l'onglet Permissions de la Fédération.",
  "Davet zorunludur, oyuncunun onayı gerekmez.": "La convocation est obligatoire ; l'accord du joueur n'est pas requis.",
  "milli takım kadrosuna alınacak ve oyuncuya bilgilendirme mesajı gönderilecek.": "sera convoqué en équipe nationale et le joueur en sera informé.",
  "milli takımdan çıkarılacak. Boşalan slot için Analiz sekmesinden yeni bir oyuncu davet etmeyi unutma.": "sera retiré de l'équipe nationale. N'oublie pas de convoquer un remplaçant depuis l'onglet Analyse.",
  "milli takımdan çıkarılacak. Boşalan slot için yeni bir oyuncu davet etmeyi unutma.": "sera retiré de l'équipe nationale. N'oublie pas de convoquer un remplaçant.",
  "Oyuncu hâlâ milli takım havuzunda kalır, daha sonra geri alabilirsin.": "Le joueur reste dans le vivier de l'équipe nationale ; tu pourras le rappeler plus tard.",
  "Milli takımla kazanacağın ilk kupa burada görünecek. Önce kadroya davet edilmen, sonra eleme grubunu geçmen gerekir.": "Ton premier trophée avec l'équipe nationale apparaîtra ici. Tu dois d'abord être convoqué, puis passer le groupe de qualification.",
  "Milli takım fikstürü sezon başında oluşturulur.": "Le calendrier de l'équipe nationale est créé en début de saison.",
