  "Lig fikstürü sezon başında oluşturulacak.": "Le calendrier du championnat sera créé en début de saison.",
  "Fikstürler oluştuğunda Toto bültenleri otomatik açılacak.": "Les bulletins Toto s'ouvriront automatiquement une fois le calendrier créé.",
