  "PO1'den düşenler · Kazanan Grup Aşamasına geçer": "Perdants du PO1 · le vainqueur accède à la Phase de groupes",
  "· Her ligin 1.si diğer ligin 2.siyle eşleşir · Kazanan Grup Aşamasına geçer": "· Le 1er de chaque championnat affronte le 2e de l'autre · le vainqueur accède à la Phase de groupes",
