  "Lig şampiyonluğu veya Avrupa kupası kazanın": "Remporte le championnat ou une coupe d'Europe",
  "İlk sezon henüz tamamlanmadı — hak kazananlar belirleniyor.": "La première saison n'est pas encore terminée — les qualifiés sont en cours de désignation.",
  "Sezon 1 · Bekleme · Hak kazananlar 1. sezon bittiğinde belirlenecek": "Saison 1 · En attente · Les qualifiés seront connus à la fin de la saison 1",
  "· Hak kazananlar 1. sezon bittiğinde belirlenecek": "· Les qualifiés seront connus à la fin de la saison 1",
  "— Sezon 2'ye geçildiğinde turnuvalar tek tıkla aktif olacak": "— Dès le début de la saison 2, les tournois s'activent en un clic",
  "gün — turnuvalar 1. sezon sonunda hak kazananlarla başlar.": "jours — les tournois commencent à la fin de la saison 1 avec les qualifiés.",
  "gün kaldı — sezon başlayınca her gün canlanacak": "jours restants — tout s'animera chaque jour dès le début de la saison",
  "sonra ilk maçlar oynanacak. Bu süreçte takımını gelişimine ve antrenmana odaklanabilirsin.": "les premiers matchs seront joués. En attendant, tu peux te concentrer sur le développement de ton équipe et l'entraînement.",
  "Pre-season devam ediyor. Sezon başladıktan sonra Gün": "La pré-saison est en cours. Après le début de la saison, au jour",
